  ensure_message('LCDP.MODULE.API_INTEGRATION.TIP.CAN_NOT_INVOKE','zh-CN','无法调用API：{0}');
  ensure_definition('LCDP.MODULE.API_INTEGRATION.TIP.EMPTY_URL','URL为空','URL为空：{0}');
