  ensure_definition('T_CORE_DATA_CENTER_USER.CREATEDBYID','个人数据中心配置的制单人编码','制单人编码');
  ensure_message('T_CORE_DATA_CENTER_USER.CREATEDBYID','zh-CN','制单人编码');
