  ensure_message('T_CORE_DATA_CENTER_USER.CREATEDBYNAME','zh-CN','制单人名称');
  ensure_definition('T_CORE_DATA_CENTER_USER.CREATEDBYORGID','个人数据中心配置的制单人单位编码','制单人单位编码');
  ensure_message('T_CORE_DATA_CENTER_USER.CREATEDBYORGID','zh-CN','制单人单位编码');
