  ensure_message('T_CORE_DATA_CENTER_USER.USERID','zh-CN','用户ID');
  ensure_definition('T_CORE_DATE_SEQUENCE.ID','系统序列的主键','主键');
  ensure_message('T_CORE_DATE_SEQUENCE.ID','zh-CN','主键');
