/
DECLARE
  definition_id NUMBER;
  message_id NUMBER;
  added_definitions PLS_INTEGER := 0;
  added_messages PLS_INTEGER := 0;
  filled_messages PLS_INTEGER := 0;
  PROCEDURE ensure_definition(code_value VARCHAR2, description_value VARCHAR2,
                              default_value VARCHAR2) IS
    n NUMBER;
  BEGIN
    SELECT COUNT(*) INTO n FROM T_CORE_I18N WHERE CODE = code_value;
    IF n > 1 THEN RAISE_APPLICATION_ERROR(-20410, 'Ambiguous existing i18n code'); END IF;
    IF n = 0 THEN
      definition_id := definition_id + 1;
      INSERT INTO T_CORE_I18N (ID,CODE,DESCRIPTION,DEFAULTMESSAGE)
        VALUES (definition_id,code_value,description_value,default_value);
      added_definitions := added_definitions + 1;
    END IF;
  END;
  PROCEDURE ensure_message(code_value VARCHAR2, locale_value VARCHAR2,
                           message_value VARCHAR2) IS
    parent_id NUMBER;
    n NUMBER;
    config_count NUMBER;
    current_message CLOB;
  BEGIN
    SELECT COUNT(*) INTO config_count FROM T_CORE_I18N_CONFIG WHERE ID = locale_value;
    IF config_count <> 1 THEN
      RAISE_APPLICATION_ERROR(-20411, 'Required locale configuration missing'); END IF;
    SELECT ID INTO parent_id FROM T_CORE_I18N WHERE CODE = code_value;
    SELECT COUNT(*) INTO n FROM T_CORE_I18N_MESSAGE
      WHERE I18NID = parent_id AND I18NCONFIGID = locale_value;
    IF n > 1 THEN RAISE_APPLICATION_ERROR(-20412, 'Ambiguous existing locale message'); END IF;
    IF n = 0 THEN
      message_id := message_id + 1;
      INSERT INTO T_CORE_I18N_MESSAGE (ID,I18NID,I18NCONFIGID,MESSAGE)
        VALUES (message_id,parent_id,locale_value,message_value);
      added_messages := added_messages + 1;
    ELSE
      SELECT MESSAGE INTO current_message FROM T_CORE_I18N_MESSAGE
        WHERE I18NID = parent_id AND I18NCONFIGID = locale_value;
      IF current_message IS NULL OR DBMS_LOB.GETLENGTH(current_message) = 0 THEN
        UPDATE T_CORE_I18N_MESSAGE SET MESSAGE = message_value
          WHERE I18NID = parent_id AND I18NCONFIGID = locale_value;
        filled_messages := filled_messages + 1;
      END IF;
    END IF;
  END;
BEGIN
  -- Include orphan references in the allocation ceiling; never adopt an old orphan.
  SELECT GREATEST(NVL((SELECT MAX(ID) FROM T_CORE_I18N),0),
                  NVL((SELECT MAX(I18NID) FROM T_CORE_I18N_MESSAGE),0))
    INTO definition_id FROM DUAL;
  SELECT NVL(MAX(ID),0) INTO message_id FROM T_CORE_I18N_MESSAGE;
  ensure_definition('T_CORE_ELN.GENERATED_TABLE','ELN实例的已生成的表格','已生成的表格');
  ensure_message('T_CORE_ELN.GENERATED_TABLE','zh-CN','已生成的表格');
