  ensure_message('T_CORE_ELN_TMPL_VERSION.ACTIVATEDBYNAME','zh-CN','启用人名称');
  ensure_definition('T_CORE_ELN_TMPL_VERSION.ACTIVATEDFLAG','ELN模板版本的状态0：停用 /1：启用','状态0：停用 /1：启用');
  ensure_message('T_CORE_ELN_TMPL_VERSION.ACTIVATEDFLAG','zh-CN','状态0：停用 /1：启用');
  ensure_definition('T_CORE_ELN_TMPL_VERSION.ACTIVATEDTIME','ELN模板版本的启用时间','启用时间');
  ensure_message('T_CORE_ELN_TMPL_VERSION.ACTIVATEDTIME','zh-CN','启用时间');
  ensure_definition('T_CORE_ELN_TMPL_VERSION.CREATEDBYID','ELN模板版本的制单人编码','制单人编码');
  ensure_message('T_CORE_ELN_TMPL_VERSION.CREATEDBYID','zh-CN','制单人编码');
