  ensure_message('T_CORE_ELN_TMPL_VERSION.CREATEDBYNAME','zh-CN','制单人');
  ensure_definition('T_CORE_ELN_TMPL_VERSION.CREATEDBYORGID','ELN模板版本的制单人单位编码','制单人单位编码');
  ensure_message('T_CORE_ELN_TMPL_VERSION.CREATEDBYORGID','zh-CN','制单人单位编码');
  ensure_definition('T_CORE_ELN_TMPL_VERSION.CREATEDBYORGNAME','ELN模板版本的制单人单位名称','制单人单位名称');
  ensure_message('T_CORE_ELN_TMPL_VERSION.CREATEDBYORGNAME','zh-CN','制单人单位名称');
  ensure_definition('T_CORE_ELN_TMPL_VERSION.CREATEDTIME','ELN模板版本的制单时间','制单时间');
