  ensure_message('T_CORE_SMS_ERROR_LOG.ERRORLOG','zh-CN','错误日志');
  ensure_definition('T_CORE_SMS_ERROR_LOG.ID','主键','主键');
  ensure_message('T_CORE_SMS_ERROR_LOG.ID','zh-CN','主键');
  ensure_definition('T_CORE_SMS_ERROR_LOG.SERVICE_NAME','短信错误日志表','短信错误日志表');
  ensure_message('T_CORE_SMS_ERROR_LOG.SERVICE_NAME','zh-CN','短信错误日志表');
