  ensure_definition('T_LCDP_RESOURCE_VERSION.CREATEDBYNAME','低代码平台资源版本表的制单人名称','制单人名称');
  ensure_message('T_LCDP_RESOURCE_VERSION.CREATEDBYNAME','zh-CN','制单人名称');
